@tool
extends Node

func run() -> Dictionary:
	var rep := {"quarantined": [], "errors": []}
	var f := FileAccess.open("res://tools/gc_cleanup_ops.json", FileAccess.READ)
	if f == null:
		rep["errors"].append({"op": "startup", "src": "ops", "error": "ops file missing"})
		return rep
	var txt := f.get_as_text()
	f.close()
	var ops = JSON.parse_string(txt)
	if ops == null:
		rep["errors"].append({"op": "startup", "src": "ops", "error": "ops JSON parse failed"})
		return rep
	var d := DirAccess.open("E:/")
	var PROJ := "ghost-company-main/"
	var QUAR := "ghost-company-quarantine/"
	for src in ops.get("quarantine", []):
		var s := String(src)
		var from_rel := PROJ + s.substr(6)
		var to_rel := QUAR + s.substr(6)
		if not (d.dir_exists(from_rel) or FileAccess.file_exists(s)):
			rep["errors"].append({"op": "quarantine", "src": s, "error": "missing"})
			continue
		var to_parent := to_rel.get_base_dir()
		if not d.dir_exists(to_parent):
			d.make_dir_recursive(to_parent)
		var err := d.rename(from_rel, to_rel)
		if err == OK:
			rep["quarantined"].append(s)
			if FileAccess.file_exists(s + ".import"):
				d.remove(from_rel + ".import")
		else:
			rep["errors"].append({"op": "quarantine", "src": s, "error": str(err)})
	return rep
